{
  "actions": {
    "actions/checkout": "3d3c42e5aac5ba805825da76410c181273ba90b1",
    "actions/dependency-review-action": "a1d282b36b6f3519aa1f3fc636f609c47dddb294",
    "actions/setup-java": "dd06d9cba3e5552c54d9f8ea23572deb30010f7c",
    "actions/setup-node": "820762786026740c76f36085b0efc47a31fe5020",
    "actions/upload-artifact": "043fb46d1a93c77aae656e7c1c64a875d1fc6a0a",
    "github/codeql-action/analyze": "cdf488f595d80d6e07e03d4674febd5ab45fa938",
    "github/codeql-action/autobuild": "cdf488f595d80d6e07e03d4674febd5ab45fa938",
    "github/codeql-action/init": "cdf488f595d80d6e07e03d4674febd5ab45fa938",
    "gradle/actions/setup-gradle": "9c971963bec38e04b3d30dcc455b5382be2fdbfb"
  },
  "containerImages": {
    "ghcr.io/gitleaks/gitleaks": {
      "version": "v8.30.1",
      "digest": "sha256:c00b6bd0aeb3071cbcb79009cb16a60dd9e0a7c60e2be9ab65d25e6bc8abbb7f"
    }
  },
  "canonicalRunner": "ubuntu-24.04",
  "requirePinnedActions": true,
  "requiredConcurrencyWorkflows": {
    "ci.yml": {
      "group": "verify-${{ github.workflow }}-${{ github.event_name }}-${{ github.event.pull_request.number || github.ref }}",
      "cancelInProgress": true
    }
  }
}

import { readFileSync, readdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const workflowRoot = join(repositoryRoot, ".github", "workflows");
const policy = JSON.parse(
  readFileSync(
    join(repositoryRoot, "contracts", "github-actions-policy.json"),
    "utf8",
  ),
);
const workflowFiles = readdirSync(workflowRoot)
  .filter((file) => /\.ya?ml$/u.test(file))
  .sort();
const observed = new Set();
const problems = [];
if (policy.requirePinnedActions !== true) {
  problems.push("GitHub Actions policy must explicitly require immutable action pins");
}

function parseJobs(lines) {
  const jobs = [];
  const jobsLine = lines.findIndex((line) => line === "jobs:");
  if (jobsLine < 0) return jobs;

  for (let index = jobsLine + 1; index < lines.length; index += 1) {
    const match = lines[index].match(/^ {2}([A-Za-z0-9_-]+):\s*$/u);
    if (!match) continue;
    const start = index;
    let end = lines.length;
    for (let cursor = index + 1; cursor < lines.length; cursor += 1) {
      if (/^ {2}[A-Za-z0-9_-]+:\s*$/u.test(lines[cursor]) || /^[A-Za-z0-9_-]+:/u.test(lines[cursor])) {
        end = cursor;
        break;
      }
    }
    jobs.push({ name: match[1], start, end });
    index = end - 1;
  }

  return jobs;
}

for (const fileName of workflowFiles) {
  const lines = readFileSync(join(workflowRoot, fileName), "utf8").split("\n");
  const jobs = parseJobs(lines);
  if (!lines.some((line) => /^permissions:\s*\{\}\s*$/u.test(line))) {
    problems.push(`${fileName} must default to permissions: {}`);
  }
  const requiredConcurrency = policy.requiredConcurrencyWorkflows?.[fileName];
  if (requiredConcurrency) {
    const expected = [
      "concurrency:",
      `  group: ${requiredConcurrency.group}`,
      `  cancel-in-progress: ${requiredConcurrency.cancelInProgress}`,
    ];
    if (!expected.every((line) => lines.includes(line))) {
      problems.push(`${fileName} must declare the required cancellable concurrency group`);
    }
  }
  for (const job of jobs) {
    if (
      !lines
        .slice(job.start, job.end)
        .some((line) => /^ {4}timeout-minutes: \d+\s*$/u.test(line))
    ) {
      problems.push(`${fileName}:${job.name} must declare timeout-minutes`);
    }
  }

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const use = line.match(/^\s*-?\s*uses:\s*([^\s#]+)(?:\s+#.*)?$/u)?.[1];
    if (use) {
      const separator = use.lastIndexOf("@");
      const action = separator >= 0 ? use.slice(0, separator) : use;
      const revision = separator >= 0 ? use.slice(separator + 1) : "";
      const expected = policy.actions[action];
      if (!expected)
        problems.push(
          `${fileName}:${index + 1} uses unapproved action ${action}`,
        );
      else if (revision !== expected)
        problems.push(
          `${fileName}:${index + 1} must pin ${action}@${expected}`,
        );
      else observed.add(action);
    }
    if (/^\s+runs-on:\s*ubuntu-latest\s*$/u.test(line)) {
      problems.push(
        `${fileName}:${index + 1} must use ${policy.canonicalRunner}, not ubuntu-latest`,
      );
    }
    if (/^\s+run:\s+(?:npm|npx)(?:\s|$)/u.test(line)) {
      problems.push(
        `${fileName}:${index + 1} must select npm through Corepack`,
      );
    }
  }
}

for (const action of Object.keys(policy.actions)) {
  if (!observed.has(action))
    problems.push(`Action policy contains unused entry ${action}`);
}

const secretScan = readFileSync(
  join(repositoryRoot, "scripts", "secret-scan.sh"),
  "utf8",
);
const gitleaksConfig = readFileSync(
  join(repositoryRoot, ".gitleaks.toml"),
  "utf8",
);
if (!secretScan.includes("--config /repo/.gitleaks.toml")) {
  problems.push("Secret scanner must load the repository Gitleaks policy");
}
for (const requiredPolicy of [
  "useDefault = true",
  'condition = "AND"',
  'regexTarget = "line"',
  ["secret", " scans, signed/provenanced releases"].join(""),
  "^docs/security-threat-model\\.md$",
  "a0657624120da26c2b22cbb634db9063ea070201",
  "^scripts/workflow-security-policy\\.mjs$",
]) {
  if (!gitleaksConfig.includes(requiredPolicy)) {
    problems.push(`Gitleaks policy must include ${requiredPolicy}`);
  }
}
for (const [image, expected] of Object.entries(policy.containerImages ?? {})) {
  const pinnedReference = `${image}@${expected.digest}`;
  if (!secretScan.includes(pinnedReference)) {
    problems.push(
      `Secret scanner must pin ${image} ${expected.version} to ${expected.digest}`,
    );
  }
}

if (problems.length > 0) {
  console.error("Workflow security policy failed:\n");
  for (const problem of problems) console.error(`- ${problem}`);
  process.exit(1);
}

console.log(
  `Workflow security policy passed: ${workflowFiles.length} workflows, ${observed.size} pinned actions, ${Object.keys(policy.containerImages ?? {}).length} pinned scanner images.`,
);

